    assert_not books(:handbook).cover.attached?

    jobs = ActiveJob::Base.queue_adapter.enqueued_jobs
    assert_empty jobs.select { |j| j[:job] == Book::SearchIndexJob }
    assert_empty jobs.select { |j| j[:job] == Book::CoverProcessingJob }
    assert jobs.any? { |j| j[:job] == Books::ImportFailureJob }
  end

  test "a successful batch goes through and hands off the work" do
    post books_import_path, params: {
      books: {
        books(:handbook).id.to_s => { title: "New Handbook", cover: fixture_file_upload("pixel.bmp", "image/bmp") },
        books(:manual).id.to_s => { title: "New Manual" }
      }
    }

