    assert_equal "New Handbook", books(:handbook).reload.title
    assert_equal "New Manual", books(:manual).reload.title

    jobs = ActiveJob::Base.queue_adapter.enqueued_jobs
    assert_equal 2, jobs.count { |j| j[:job] == Book::SearchIndexJob }
    assert_equal 1, jobs.count { |j| j[:job] == Book::CoverProcessingJob }
    assert_empty jobs.select { |j| j[:job] == Books::ImportFailureJob }
  end
end
